ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  PayerProductInstanceReference: {
    ProductReference: {
      ProductIdentification: {
        ProductIdentification: {
          IdentifierValue: { Value: payload.cuentaOrigen }
        }
      }
    }
  },
  PayeeProductInstanceReference: {
    ProductReference: {
      ProductIdentification: {
        ProductIdentification: {
          IdentifierValue: { Value: payload.cuentaDestino }
        }
      }
    }
  },
  PayeeBankReference: {
    PartyReference: {
      PartyIdentification: {
        PartyIdentification: {
          IdentifierValue: { Value: payload.bancoDestino }
        }
      }
    }
  },
  Amount: {
    AmountValue:    { Value: payload.monto as String },
    AmountCurrency: { Currencycode: payload.moneda default "USD" }
  },
  Currency:              { Currencycode: payload.moneda default "USD" },
  DateType:              "Creationdate",
  Date:                  { DateTimeContent: payload.fechaSolicitud },
  PaymentMechanismType:  "ACH",
  PaymentInstructions:   { PaymentInstructionType: "Domesticpayment" },
  RemittanceInformation: { Text: payload.concepto }
}

%dw 2.0
output application/json
---
{
  codigo:        "IDEMPOTENCY_CONFLICT",
  mensaje:       "La clave X-Idempotency-Key ya fue utilizada con un cuerpo de solicitud diferente.",
  correlationId: vars.transactionId default "",
  timestamp:     now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"}
}
